def matches(row, rule):
    value = row[rule["field"]]
    threshold = rule["threshold"]
    return {"eq": value == threshold, "gte": value >= threshold, "lte": value <= threshold}[rule["operator"]]
def apply_selection(rows, stages):
    for stage in stages:
        if stage["op"] == "sort":
            rows = sorted(rows, key=lambda row: row[stage["field"]], reverse=stage.get("descending", False))
        elif stage["op"] == "limit":
            rows = rows[:stage["count"]]
    return rows
def validate_contract(contract, sources):
    required = {"candidates", "criteria", "select"}
    return required <= contract.keys() and all(row["source_id"] in sources for row in contract["candidates"])
def execute_contract(contract, sources):
    rows = [row for row in contract["candidates"] if all(matches(row, rule) for rule in contract["criteria"])]
    return apply_selection(rows, contract["select"])
def answer(system, question):
    sources = {source.id: source for source in system.retrieve_complete_pool(question)}
    contract = system.model.emit_json_contract(question, sources)
    if not validate_contract(contract, sources):
        raise ValueError("invalid research contract")
    solved = execute_contract(contract, sources)
    return system.deterministic_renderer.render(solved, sources)

